import React from 'react';
import { Link } from 'react-router-dom';

const NoteList = ({ notes }) => (
  <div>
    <h2>Daftar Catatan</h2>
    <ul>
      {notes.map((note) => (
        <li key={note.id}>
          <Link to={`/notes/${note.id}`}>{note.title}</Link>
        </li>
      ))}
    </ul>
  </div>
);

export default NoteList;
